import React, { useState, useEffect } from 'react';
import './Achat.css';

function Achat({ allerVers, utilisateur, musiqueId }) {
  const [musique, setMusique] = useState(null);
  const [operateur, setOperateur] = useState('mtn');
  const [numero, setNumero] = useState('');
  const [etape, setEtape] = useState('paiement');
  const [chargement, setChargement] = useState(false);
  const [message, setMessage] = useState('');

  useEffect(() => {
    fetch('/api/musiques')
      .then(res => res.json())
      .then(data => {
        const m = data.musiques.find(m => m.id === parseInt(musiqueId));
        setMusique(m);
      });
  }, [musiqueId]);

  const handlePaiement = async () => {
    if (!utilisateur) {
      allerVers('login');
      return;
    }

    if (!numero) {
      setMessage('❌ Entrez votre numéro Mobile Money !');
      return;
    }

    setChargement(true);
    setMessage('');

    try {
      const reponse = await fetch('/api/achats', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          acheteur_id: utilisateur.id,
          musique_id: parseInt(musiqueId),
          operateur,
          numero_paiement: numero
        })
      });

      const donnees = await reponse.json();

      if (reponse.ok) {
        setEtape('succes');
      } else {
        setMessage('❌ ' + donnees.message);
      }

    } catch (erreur) {
      setMessage('❌ Impossible de contacter le serveur');
    }

    setChargement(false);
  };

  if (!musique) return <div className="achat-page"><div className="chargement">Chargement...</div></div>;

  if (etape === 'succes') {
    return (
      <div className="achat-page">
        <div className="achat-box">
          <div className="succes-icone">🎉</div>
          <h2 className="succes-titre">Paiement réussi !</h2>
          <p className="succes-texte">
            <strong>{musique.titre}</strong> a été ajouté à votre bibliothèque.
          </p>
          <p className="succes-detail">
            {musique.prix} FCFA débités sur votre compte {operateur.toUpperCase()} ({numero})
          </p>
          <button className="btn-bibliotheque" onClick={() => allerVers('bibliotheque')}>
            🎵 Voir ma bibliothèque
          </button>
          <button className="btn-retour-catalogue" onClick={() => allerVers('catalogue')}>
            ← Retour au catalogue
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="achat-page">
      <div className="achat-box">
        <h1 className="achat-logo">🎵 Varim Music</h1>
        <h2 className="achat-titre">Finaliser l'achat</h2>

        <div className="achat-recap">
          {musique.pochette_url && (
            <img src={musique.pochette_url} alt={musique.titre} className="achat-pochette" />
          )}
          <div className="achat-info">
            <h3>{musique.titre}</h3>
            <p>🎤 {musique.nom_artiste}</p>
            <p className="achat-type">{musique.type === 'album' ? '💿 Album' : '🎵 Single'}</p>
            <p className="achat-prix">{musique.prix} FCFA</p>
          </div>
        </div>

        {message && <div className="achat-message">{message}</div>}

        <div className="achat-champ">
          <label>Choisir l'opérateur</label>
          <div className="operateurs">
            <div
              className={`operateur-carte ${operateur === 'mtn' ? 'active' : ''}`}
              onClick={() => setOperateur('mtn')}
            >
              <span className="operateur-logo mtn">MTN</span>
              <span>Mobile Money</span>
            </div>
            <div
              className={`operateur-carte ${operateur === 'airtel' ? 'active' : ''}`}
              onClick={() => setOperateur('airtel')}
            >
              <span className="operateur-logo airtel">Airtel</span>
              <span>Money</span>
            </div>
          </div>
        </div>

        <div className="achat-champ">
          <label>Numéro {operateur === 'mtn' ? 'MTN' : 'Airtel'}</label>
          <input
            type="tel"
            placeholder="Ex: 06 123 45 67"
            value={numero}
            onChange={(e) => setNumero(e.target.value)}
          />
        </div>

        <div className="achat-total">
          <span>Total à payer</span>
          <span className="total-prix">{musique.prix} FCFA</span>
        </div>

        {!utilisateur && (
          <p className="achat-connexion">
            ⚠️ <a href="#" onClick={() => allerVers('login')}>Connectez-vous</a> pour acheter
          </p>
        )}

        <button
          className="achat-btn"
          onClick={handlePaiement}
          disabled={chargement}
        >
          {chargement ? 'Traitement en cours...' : `Payer ${musique.prix} FCFA`}
        </button>

        <button className="btn-annuler" onClick={() => allerVers('catalogue')}>
          Annuler
        </button>
      </div>
    </div>
  );
}

export default Achat;
